mapper.select:
SELECT ps.`id`, -- 招标科目表id ps.subject_names, -- 品名 bs.name AS subjectName, -- 末级科目名称 ps.specification, -- 规格 ps.model_number, -- 型号 ps.mete, -- 采购量 ps.unit_name, -- 单位名称 s.name AS supplierName, -- 供应商名称 br.round, -- 招标轮次 ss.is_follow, -- 结果 ods.bid_amount, -- 总价 ods.unit_price, -- 单价 ods.is_follow -- 是否中标 FROM project_subject ps LEFT JOIN project_tendering_supplier ptr ON ptr.`project_tendering_id` = ps.project_id LEFT JOIN bidding_rounds br ON br.project_id = ps.project_id LEFT JOIN offer_rounds ors ON ors.supplier_id = ptr.id AND ors.offer_round = br.round and ors.project_tendering_id = ps.project_id
AND ors.is_hold = #{isHold}
LEFT JOIN offer_round_detail ods ON ods.offer_id = ors.`id` AND ods.project_subject_id = ps.`id` and ods.project_id = ps.project_id LEFT JOIN supplier_subject ss on ss.supplier_id = ptr.id AND ss.project_id = ps.`project_id` AND ss.project_subject_id = ps.id LEFT JOIN subject bs on bs.id = ps.subject_id LEFT JOIN supplier s on s.id = ptr.bid_supplier_id WHERE ps.`project_id` = #{projectId} AND ptr.`id` = #{supplierId}

SELECT pts.id, pts.bid_supplier_id AS supplierId, pts.bid_status, pts.bidding_time, ss.name AS supplierName, -- 供应商全称 sd.short_name, -- 供应商简称 sd.contact_phone AS phone FROM project_tendering_supplier pts LEFT JOIN supplier ss on ss.id = pts.bid_supplier_id LEFT JOIN supplier_detail sd on sd.supplier_id = pts.bid_supplier_id WHERE pts.`project_tendering_id` = #{projectId}
AND pts.bid_supplier_id in
#{item}
order by pts.bid_status DESC
